const t=k=>(words[s.lang||'lv'][k]||k),dom=id=>document.getElementById('fm-'+id);function localStatus(v){return ({verified_source_attribute:t('sourceVerified'),verified:t('cadastralVerified'),boundary_review_required:t('boundaryReview'),geometry_invalid:t('geometryInvalid'),display_review_required:t('displayReview'),source_conflict:t('sourceConflict'),spatial_candidate_only:t('spatialOnly'),READY:t('statusReady'),'REVIEW REQUIRED':t('statusReview'),'ALREADY IMPORTED':t('statusExisting')})[v]||v||'—';}
const fmt=n=>Number(n).toLocaleString(s.lang==='en'?'en-US':'lv-LV');
const SERVER_TEXT={'Map is busy; retry this tile':'mapBusy','Forest compartment not found':'featureNotFound','Source geometry is too complex for direct inspection; use cadastral review':'noticeComplex','Coordinates must be in Latvia':'invalidCoords','Compartment is not in the production dataset':'reasonNotInDataset','Nogabala avota kadastra apzīmējums neatbilst pārbaudītajai atlasei':'reasonCadMismatch','Kadastra saistība nav pārbaudīta; reģistrācija nav atļauta':'reasonAssocUnverified','Avota vai attēlojuma ģeometrijai nepieciešama manuāla pārbaude':'reasonManual','Current sectors require one simple Polygon ring; MultiPolygon/holes are not flattened':'rs_unsupported','A sector with this name already exists; no overwrite allowed':'reasonNameExists','Source identity conflict; nothing overwritten':'reasonIdentity'};
const translated=text=>SERVER_TEXT[text]?t(SERVER_TEXT[text]):text;
const NOTICE={zoom_in:'noticeZoom',dense:'noticeDense',complex:'noticeComplex',none:'none'};
function associationLabel(p){const v=p.cadastral_validation||{},a=p.cadastral_association||{};if(v.status==='display_review_required')return t('displayReview');if(!v.registration_allowed)return t('cadastralUnverified')+' · '+(a.status==='verified_source_attribute'?t('sourceVerified'):t('sourceUnverified'));return a.status==='verified_source_attribute'?t('sourceVerified'):a.classification==='derived'?t('derived'):t('notVerified');}
function reviewReason(p){if(p.importable)return null;const v=p.cadastral_validation||{},a=p.cadastral_association||{};let key;
 if(p.sector)return [t('rs_existing').replace('{name}',p.sector.name),t('nx_existing')];
 if(!p.geometry_valid||v.status==='geometry_invalid')key='geometry_invalid';else if(p.geometry_repaired||v.status==='display_review_required')key='display_review';else if(p.import_status==='UNSUPPORTED GEOMETRY')key='unsupported';else if(v.status==='source_conflict')key='source_conflict';else if(v.status==='spatial_candidate_only')key='spatial';else if(v.status==='boundary_review_required')key='boundary';else if(a.status!=='verified_source_attribute')key='unverified';else key='boundary';
 return [t('rs_'+key).replace('{overlap}',overlapText(v)).replace('{outside}',outsideText(v)),t('nx_'+key)];}
// Never round a partial containment up to 100%: add decimals until the value is below 100, and give the outside area.
function percentBelow100(p){if(p>=100)return '100';for(let d=2;d<=12;d++){const x=Number(p).toFixed(d);if(Number(x)<100)return x;}return '99.999999999999';}
function areaM2(a){const loc=s.lang==='en'?'en-US':'lv-LV';return a<0.01?'< '+(0.01).toLocaleString(loc):Number(a).toLocaleString(loc,{minimumFractionDigits:a<10?2:1,maximumFractionDigits:a<10?2:1});}
function overlapText(v){if(v.overlap_percent==null)return '—';const pct=percentBelow100(Number(v.overlap_percent));return (s.lang==='en'?pct:pct.replace('.',','))+'%';}
function outsideText(v){return v.outside_area_m2==null?'':t('outsideM2').replace('{a}',areaM2(Number(v.outside_area_m2)));}
function areaText(p){return p.area_ha==null?'—':Number(p.area_ha).toFixed(2)+' ha'+(p.area_declared===false?' ('+t('areaComputed')+')':'');}
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
function node(tag,text,parent){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(parent)parent.append(n);return n;}
function message(text){dom('status').textContent=text;}
function button(parent,key,fn,id){const b=node('button',t(key),parent);b.className='btn';b.type='button';if(id)b.id='fm-'+id;b.onclick=()=>Promise.resolve().then(fn).catch(error=>message(error.message));return b;}
function panel(parent,title,id){const p=node('section',undefined,parent);p.className='forest-map-panel';if(id)p.id='fm-'+id;node('h3',t(title),p);return p;}
function input(parent,key,id){const label=node('label',t(key),parent);label.htmlFor='fm-'+id;const i=node('input',undefined,parent);i.id='fm-'+id;return i;}
async function request(path,body,signal){const c=new AbortController(),abort=()=>c.abort(),timer=setTimeout(abort,35000);signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted)c.abort();try{const r=await fetch(path,{credentials:'same-origin',cache:'no-store',signal:c.signal,...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?translated(data.detail):t('error')+' ('+r.status+')');return data;}finally{clearTimeout(timer);signal?.removeEventListener('abort',abort);}}
