 const root=document.getElementById('sec-forest-map');root.replaceChildren();
 const legend=node('div',undefined,root);legend.className='forest-map-legend';[['available','#70bc7b'],['selected','#e2b64b'],['existing','#b990ef'],['review','#e7a456'],['parcels','#62ccf2']].forEach(([key,color])=>{const n=node('span',t(key),legend);n.className='forest-map-key';n.style.setProperty('--key',color);});
 const shell=node('div',undefined,root);shell.className='forest-map-shell';const sidebar=node('div',undefined,shell);sidebar.className='forest-map-sidebar';violationsPanel(sidebar);
 const search=panel(sidebar,'search');const language=node('select',undefined,search);language.id='fm-language';language.className='forest-map-lang';language.setAttribute('aria-label','Language / Valoda');[['en','EN'],['lv','LV']].forEach(([v,label])=>{const o=node('option',label,language);o.value=v;});language.value=s.lang;language.onchange=()=>setLanguage(language.value);
 node('div',t('local'),search).className='forest-map-map-title';const records=node('div','—',search);records.id='fm-record-count';records.className='forest-map-count';
 const cad=input(search,'cadastre','cadastre');cad.inputMode='numeric';cad.maxLength=11;cad.onkeydown=e=>{if(e.key==='Enter')find();};button(search,'find',find,'find');const source=input(search,'sourceSearch','source-search');source.maxLength=200;source.onkeydown=e=>{if(e.key==='Enter')findSource();};button(search,'findSource',findSource,'findSource');const municipality=input(search,'municipalitySearch','municipality-search');municipality.maxLength=254;municipality.onkeydown=e=>{if(e.key==='Enter')findMunicipality(0);};button(search,'findMunicipality',()=>findMunicipality(0),'findMunicipality');
