 const layers=panel(sidebar,'layers','layers');const baseLabel=node('label',t('basemap'),layers);baseLabel.htmlFor='fm-basemap';const base=node('select',undefined,layers);base.id='fm-basemap';base.setAttribute('aria-label',t('basemap'));['satellite','standard'].forEach(key=>{const o=node('option',t(key),base);o.value=key;});base.onchange=()=>setBasemap(base.value);
