 const canvas=node('div',undefined,shell);canvas.className='forest-map-canvas';const view=node('div',undefined,canvas);view.id='fm-map';view.className='forest-map-view';view.setAttribute('aria-label',t('title'));const badge=node('div',t('overview'),canvas);badge.id='fm-scale';badge.className='forest-map-badge';renderSelection();
