function pump(){while(s.running<3&&s.queue.length){const job=s.queue.shift();if(job.controller.signal.aborted){job.done(null,job.canvas);continue;}s.running++;loadTile(job).finally(()=>{s.running--;pump();});}}
async function loadTile(job){const {coords,canvas,done,controller,kind}=job;try{let r;for(let attempt=0;;attempt++){r=await fetch('/api/geodata/forest-map/tiles/'+kind+'/'+coords.z+'/'+coords.x+'/'+coords.y+'?v='+encodeURIComponent(s.version||''),{credentials:'same-origin',signal:controller.signal});if(r.status!==503||attempt>=2)break;s.stats.retries=(s.stats.retries||0)+1;await sleep(700*(attempt+1));if(controller.signal.aborted)throw new DOMException('aborted','AbortError');}if(!r.ok)throw Error('Tile '+r.status);const text=await r.text();if(controller.signal.aborted){done(null,canvas);return;}const data=JSON.parse(text);if(s.version&&data.dataset_version!==s.version)throw Error(t('version'));const t0=performance.now();drawTile(canvas,data,coords,kind);s.stats.drawMs=(s.stats.drawMs||0)+performance.now()-t0;s.stats.tiles++;s.stats.maxBytes=Math.max(s.stats.maxBytes,text.length);s.stats.maxFeatures=Math.max(s.stats.maxFeatures,data.features.length);canvas.dataset.mode=data.mode;scaleNotice();done(null,canvas);}catch(error){if(error.name==='AbortError'){s.stats.aborted++;done(null,canvas);}else{s.stats.errors++;message(t('retry'));done(error,canvas);}}}
function drawTile(canvas,data,coords,kind){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,256,256);canvas._fmHit=[];
 if(data.cells){const c=data.cells,size=c.zoom>=coords.z?256/2**(c.zoom-coords.z):256*2**(coords.z-c.zoom),cell=Math.max(1,size);for(let i=0;i<c.count.length;i++){const x=(c.x0+c.dx[i])*size-coords.x*256,y=(c.y0+c.dy[i])*size-coords.y*256;ctx.fillStyle='rgba(82,169,105,'+(0.12+0.6*Math.min(1,Math.log1p(c.count[i])/Math.log1p(250))).toFixed(3)+')';ctx.fillRect(x,y,cell,cell);}return;}
 for(const feature of data.features){const p=feature.properties||{};if(data.mode==='generalized_presence'&&feature.geometry.type==='Point'){const projected=s.map.project(L.latLng(feature.geometry.coordinates[1],feature.geometry.coordinates[0]),coords.z),x=projected.x-coords.x*256,y=projected.y-coords.y*256;ctx.beginPath();ctx.arc(x,y,Math.min(9,4+Math.log2(Math.max(1,p.compartment_count||1))),0,Math.PI*2);ctx.fillStyle='rgba(112,188,123,.78)';ctx.fill();continue;}
 const polygons=feature.geometry.type==='Polygon'?[feature.geometry.coordinates]:feature.geometry.type==='MultiPolygon'?feature.geometry.coordinates:[];const rings=[];ctx.beginPath();
 for(const polygon of polygons)for(const ring of polygon){const pts=[];ring.forEach((position,i)=>{const projected=s.map.project(L.latLng(position[1],position[0]),coords.z),x=projected.x-coords.x*256,y=projected.y-coords.y*256;pts.push(x,y);i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.closePath();rings.push(pts);}
 if(kind==='forest')canvas._fmHit.push({p,rings});
 ctx.strokeStyle=kind==='parcels'?'#62ccf2':p.review_required?'#e7a456':'#74c484';ctx.lineWidth=kind==='parcels'?1:1.1;ctx.fillStyle=p.review_required?'rgba(231,164,86,.16)':data.mode==='generalized_presence'?'rgba(82,169,105,.38)':'rgba(85,172,107,.17)';if(kind!=='parcels')ctx.fill('evenodd');if(data.mode!=='generalized_presence'||kind==='parcels')ctx.stroke();}}
function inside(rings,x,y){let hit=false;for(const r of rings)for(let i=0,j=r.length-2;i<r.length;j=i,i+=2){const xi=r[i],yi=r[i+1],xj=r[j],yj=r[j+1];if((yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi)hit=!hit;}return hit;}
let hoverAt=0;
function hover(event){const now=performance.now();if(now-hoverAt<80)return;hoverAt=now;const z=s.map.getZoom(),layer=s.layers.forest;let found=null;
 if(z>=13&&layer&&s.map.hasLayer(layer)){const pt=s.map.project(event.latlng,z),tx=Math.floor(pt.x/256),ty=Math.floor(pt.y/256),el=layer._tiles?.[tx+':'+ty+':'+z]?.el;if(el?._fmHit){const x=pt.x-tx*256,y=pt.y-ty*256;for(let i=el._fmHit.length-1;i>=0;i--)if(inside(el._fmHit[i].rings,x,y)){found=el._fmHit[i].p;break;}}}
 if(!found){if(s.hover)s.map.removeLayer(s.hover);return;}
 const text=found.kadastrs+' · K'+(found.kvart??'—')+' N'+(found.nog??'—')+' · '+areaText(found);
 if(!s.hover)s.hover=L.tooltip({direction:'top',offset:[0,-8],className:'forest-map-hover'});s.hover.setLatLng(event.latlng).setContent(text);if(!s.map.hasLayer(s.hover))s.hover.addTo(s.map);}
function makeTiles(kind){const Class=L.GridLayer.extend({createTile(coords,done){const canvas=document.createElement('canvas');canvas.width=canvas.height=256;const controller=new AbortController();canvas._fmController=controller;s.queue.push({kind,coords,canvas,done,controller});pump();return canvas;}});const layer=new Class({tileSize:256,keepBuffer:1,maxZoom:19,minZoom:4,noWrap:true,bounds:[[55.4,20.4],[58.5,28.7]],updateWhenIdle:true,updateWhenZooming:false,pane:kind==='forest'?'fmForest':'fmParcels'});layer.on('tileunload',e=>e.tile._fmController?.abort());return layer;}
/* Basemap: one source of truth for the on-map control and the sidebar select. Basemap tiles stay in
   Leaflet's tilePane (z 200); every overlay (VMD, VZD, sectors, GPS, violations) lives in a higher pane. */
const BASEMAP_KEY='forestMap.basemap',BASEMAPS=['satellite','standard'];
function savedBasemap(){try{const v=global.localStorage?.getItem(BASEMAP_KEY);return BASEMAPS.includes(v)?v:null;}catch(e){return null;}}
function storeBasemap(v){try{global.localStorage?.setItem(BASEMAP_KEY,v);}catch(e){}}
function setBasemap(value,persist=true){if(!s.map)return;let kind=BASEMAPS.includes(value)?value:'satellite';if(kind==='satellite'&&s.satelliteFailed)kind='standard';for(const key of BASEMAPS)if(s.layers[key]&&s.map.hasLayer(s.layers[key]))s.map.removeLayer(s.layers[key]);s.layers[kind].addTo(s.map);s.layers[kind].bringToBack?.();s.basemap=kind;if(persist&&kind===value)storeBasemap(kind);syncBasemap();}
function syncBasemap(){const select=dom('basemap');if(select){select.value=s.basemap||'satellite';const o=select.querySelector('option[value="satellite"]');if(o)o.disabled=!!s.satelliteFailed;}for(const b of s.basemapButtons||[]){const on=b.dataset.basemap===s.basemap;b.setAttribute('aria-pressed',String(on));b.classList.toggle('active',on);if(b.dataset.basemap==='satellite'){b.disabled=!!s.satelliteFailed;b.title=s.satelliteFailed?t('satelliteFailed'):'';}}if(s.basemapNote){s.basemapNote.hidden=!s.satelliteFailed;s.basemapNote.textContent=s.satelliteFailed?t('satelliteFailed'):'';}}
function watchSatellite(layer){let errors=0,loaded=false;layer.on('tileload',()=>{loaded=true;});layer.on('tileerror',()=>{if(loaded||s.satelliteFailed||++errors<3)return;s.satelliteFailed=true;if(s.basemap==='satellite')setBasemap('standard',false);else syncBasemap();message(t('satelliteFailed'));});}
