function toggleLayer(kind,visible){if(kind==='violations'){if(s.gps.vlayer){if(visible)s.gps.vlayer.addTo(s.map);else s.map.removeLayer(s.gps.vlayer);}const p=dom('violations');if(p)p.hidden=!visible;if(visible)loadOverview();return;}if(kind==='selected')s.selectedVisible=visible;if(kind==='parcels'&&s.parcel){if(visible)s.parcel.addTo(s.map);else s.map.removeLayer(s.parcel);}if(kind==='gps'){for(const l of [s.gps.layer,s.gps.track])if(l){if(visible)l.addTo(s.map);else s.map.removeLayer(l);}if(visible)loadGps();return;}const layer=kind==='sectors'?s.sectors:kind==='selected'?s.selectionLayer:s.layers[kind];if(kind==='forest'&&s.matchLayer){if(visible)s.matchLayer.addTo(s.map);else s.map.removeLayer(s.matchLayer);}if(layer){if(visible)layer.addTo(s.map);else s.map.removeLayer(layer);}}
