async function preview(){if(s.busy||!s.selected.size){message(t('noSelection'));return;}const {name='',first='',last=''}=s.registration||{};if(!name||!first||!last)throw Error(t('name')+' / '+t('first')+' / '+t('last'));const groups=new Map();for(const f of s.selected.values()){const cad=f.properties.kadastrs;if(!groups.has(cad))groups.set(cad,[]);groups.get(cad).push(f.id);}const bodies=Array.from(groups,([cad,ids])=>({feature_ids:ids,dataset_version:s.version,cadastral_designation:cad,sector_name:groups.size>1?name+' · '+cad:name,responsible_first_name:first,responsible_last_name:last,dry_run:true}));if(bodies.some(b=>b.sector_name.length>120))throw Error(t('nameTooLong'));s.busy=true;renderSelection();message(t('busy'));try{const results=[];for(const body of bodies)results.push(await request('/api/geodata/vmd/import-selected',body));s.preview={bodies,results};showReview(bodies,results);}finally{s.busy=false;renderSelection();}}
